  const style=document.createElement('style');style.id='fsffl-league-atlas-v1-style';
  style.textContent='.league-structure-panel{padding:0!important;background:transparent!important;border:0!important;box-shadow:none!important}.league-structure-hero{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(280px,.85fr);gap:16px;margin-bottom:16px}.league-structure-hero>div:first-child,.league-takeaway,.league-section,.league-pressure,.league-detail{border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,#0b1424,#09101d);box-shadow:0 16px 34px rgba(0,0,0,.16)}.league-structure-hero>div:first-child{padding:22px}.league-takeaway{padding:20px;display:flex;flex-direction:column;justify-content:center;gap:8px}.league-takeaway span,.league-section-heading>small,.league-value-toolbar>span{color:var(--muted);font-size:10px}.league-section{padding:18px;margin:14px 0}.league-section-heading{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:14px}.league-edge-matrix{overflow-x:auto;border:1px solid var(--line);border-radius:14px}.league-edge-row{display:grid;grid-template-columns:minmax(150px,1.4fr) repeat(4,minmax(74px,.7fr));min-width:520px;border-top:1px solid var(--line)}.league-edge-row:first-child{border-top:0}.league-edge-row.header{font-size:10px;color:var(--muted);text-transform:uppercase}.league-edge-row>span{padding:9px 10px}.league-edge-cell{display:flex;align-items:center;justify-content:center;gap:5px;border-left:1px solid var(--line)}.league-edge-cell small{font-size:9px;color:var(--muted)}.league-edge-cell.elite{background:rgba(54,211,153,.13)}.league-edge-cell.strong{background:rgba(78,156,255,.10)}.league-edge-cell.weak{background:rgba(239,103,103,.08)}.league-edge-team{display:grid}.league-edge-team small{color:#63aafc;font-size:9px}.league-edge-row.managed{background:rgba(46,142,255,.05)}.league-value-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:10px}.league-value-modes{display:flex;gap:6px;flex-wrap:wrap}.league-value-modes button{border:1px solid var(--line);border-radius:999px;background:#08101c;color:var(--muted);padding:7px 10px;font-size:10px;font-weight:700}.league-value-modes button.active{color:#fff;border-color:#3d83c9;background:#10243a}.league-value-axis{display:grid;grid-template-columns:1fr 1fr 1fr;padding:0 8px 5px 150px;color:var(--muted);font-size:9px}.league-value-axis span:nth-child(2){text-align:center}.league-value-axis span:last-child{text-align:right}.league-value-grid{border:1px solid var(--line);border-radius:14px;overflow:hidden}.league-value-row{width:100%;display:grid;grid-template-columns:140px minmax(0,1fr);gap:10px;align-items:center;border:0;border-top:1px solid var(--line);background:#09111e;color:inherit;padding:9px 10px;text-align:left}.league-value-row:first-child{border-top:0}.league-value-row.selected{box-shadow:inset 0 0 0 1px #3d83c9}.league-value-team{display:grid;min-width:0}.league-value-team strong{font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.league-value-team small{font-size:9px;color:var(--muted)}.league-value-strip{position:relative;height:22px;border-left:1px solid var(--line);border-right:1px solid var(--line);background:linear-gradient(90deg,transparent 49.7%,rgba(255,255,255,.12) 50%,transparent 50.3%)}.league-value-dot{position:absolute;top:50%;width:7px;height:7px;border-radius:50%;transform:translate(-50%,-50%);background:#7ca8db}.league-value-dot.pos-rb{background:#8ee0bd}.league-value-dot.pos-wr{background:#d6a5ff}.league-value-dot.pos-te{background:#f2cc7e}.league-value-detail{margin-top:10px;border:1px solid var(--line);border-radius:12px;padding:11px}.league-value-detail>div:first-child{display:flex;justify-content:space-between}.league-value-player-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin-top:8px}.league-value-player{display:grid;grid-template-columns:minmax(0,1fr) repeat(3,auto);gap:8px;align-items:center;border:1px solid var(--line);border-radius:9px;padding:8px}.league-value-player>div,.league-value-player>span{display:grid}.league-value-player>span{text-align:right}.league-value-player small{font-size:8px;color:var(--muted)}.league-pressure{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(240px,.9fr) auto;gap:16px;align-items:center;padding:18px;margin:14px 0}.league-pressure p{color:var(--muted);font-size:11px}.league-supply-list{display:grid;gap:6px}.league-supply-team{display:grid;grid-template-columns:auto 1fr auto;gap:8px;font-size:10px}.league-two-column{display:grid;grid-template-columns:1fr 1fr;gap:14px}.league-state-lanes,.league-age-track,.league-pick-band{display:grid;gap:7px}.league-state-lane,.league-age-row,.league-depth-row{border:1px solid var(--line);border-radius:10px;padding:9px}.league-state-lane>div:first-child{display:flex;justify-content:space-between}.league-team-chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:6px}.league-team-chip{border:1px solid var(--line);border-radius:999px;padding:4px 7px}.league-team-chip small{font-size:8px;color:var(--muted)}.league-age-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:10px}.league-age-reading{display:grid;text-align:right}.league-age-reading span{font-size:8px;color:var(--muted)}.league-pick-row{display:grid;grid-template-columns:minmax(120px,1fr) minmax(120px,2fr) auto;gap:10px;align-items:center}.league-pick-row>div{display:grid}.league-pick-row small{font-size:8px;color:var(--muted)}.league-pick-row>i{height:8px;border-radius:999px;background:#08101c;border:1px solid var(--line);overflow:hidden}.league-pick-row>i>b{display:block;height:100%;background:#4e9cff}.league-detail{margin:14px 0}.league-detail summary{padding:15px 18px;font-weight:700}.league-detail>p,.league-evidence-copy{padding:0 18px 16px;color:var(--muted);font-size:11px;line-height:1.5}.league-depth-grid{padding:0 18px 18px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.league-depth-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:10px}.league-depth-row>span{display:grid;text-align:right}.league-depth-row small{font-size:8px;color:var(--muted)}@media(max-width:900px){.league-structure-hero,.league-two-column{grid-template-columns:1fr}.league-pressure{grid-template-columns:1fr}.league-value-player-grid,.league-depth-grid{grid-template-columns:1fr}.league-section-heading,.league-value-toolbar{align-items:flex-start;flex-direction:column}}@media(max-width:560px){.league-structure-hero>div:first-child,.league-takeaway,.league-section,.league-pressure{border-radius:14px;padding:14px}.league-edge-row{grid-template-columns:minmax(125px,1.25fr) repeat(4,minmax(63px,.7fr));min-width:440px}.league-value-axis{padding-left:105px}.league-value-row{grid-template-columns:95px minmax(0,1fr);gap:7px}.league-value-player{grid-template-columns:minmax(0,1fr) repeat(3,34px)}.league-pick-row{grid-template-columns:minmax(90px,1fr) minmax(90px,1.5fr) auto}}';
